"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["15481"],{68435(e){e.exports=JSON.parse('{"id":"V4-002","slug":"car-insurance","term":"Car Insurance","also_known_as":[],"difficulty":"Beginner","definition":"Car insurance is insurance that covers financial losses related to owning and driving a vehicle, including damage to other people and their property and, depending on the policy, damage to or theft of the insured car.","explanation":["In most countries, drivers are legally required to have at least a minimum level of car insurance, covering injury to other people and damage to their property. This protects victims of accidents caused by the insured driver.","Policies usually come in levels. Third-party cover pays only for damage and injury to others. Third-party, fire and theft adds cover if the car is stolen or damaged by fire. Comprehensive cover also pays for damage to the policyholder\u2019s own car, even if the accident was their fault.","For example, a driver with comprehensive cover who damages their car in an accident they caused could claim for repairs, paying the policy excess, while their insurer would also cover damage to the other driver\u2019s vehicle.","Premiums depend on factors such as the driver\u2019s age, driving record, location, the car\u2019s value and type, annual mileage and where it is parked. Making claims can increase future premiums or reduce no-claims discounts, so drivers sometimes choose to pay for small repairs themselves. In the United States, car insurance is commonly called auto insurance."],"note":"","total":1725,"prev":{"slug":"captive-insurer","term":"Captive Insurer"},"next":{"slug":"carbon-credit","term":"Carbon Credit"}}')}}]);